      {data ? <ProductGrid products={data.items} /> : <p>Loading products...</p>}
    </>
  );
}

import { create } from "zustand";

export type CartItem = {
  slug: string;
  quantity: number;
};

type CartState = {
  items: CartItem[];
  addItem: (slug: string) => void;
  removeItem: (slug: string) => void;
  clear: () => void;
};

export const useCartStore = create<CartState>()((set) => ({
  items: [],

  addItem: (slug) =>
    set((state) => {
      const inCart = state.items.some((item) => item.slug === slug);
      return {
        items: inCart
          ? state.items.map((item) =>
              item.slug === slug
                ? { ...item, quantity: Math.min(item.quantity + 1, 10) }
                : item,
            )
          : [...state.items, { slug, quantity: 1 }],
      };
    }),

  removeItem: (slug) =>
    set((state) => ({ items: state.items.filter((item) => item.slug !== slug) })),

  clear: () => set({ items: [] }),
}));

export function selectItemCount(state: CartState) {
  return state.items.reduce((sum, item) => sum + item.quantity, 0);
}

