import { create } from "zustand";
import { devtools, persist } from "zustand/middleware";

export type CartItem = {
  slug: string;
  quantity: number;
};

type CartState = {
  items: CartItem[];
  isOpen: boolean;
  addItem: (slug: string) => void;
  setOpen: (isOpen: boolean) => void;
  clear: () => void;
};

export const useCartStore = create<CartState>()(
  devtools(
    persist(
      (set) => ({
        items: [],
        isOpen: false,

        addItem: (slug) =>
          set(
            (state) => ({
              items: state.items.some((item) => item.slug === slug)
                ? state.items.map((item) =>
                    item.slug === slug
                      ? { ...item, quantity: Math.min(item.quantity + 1, 10) }
                      : item,
                  )
                : [...state.items, { slug, quantity: 1 }],
            }),
            undefined,
            "cart/addItem",
          ),

        setOpen: (isOpen) => set({ isOpen }, undefined, "cart/setOpen"),

        clear: () => set({ items: [] }, undefined, "cart/clear"),
      }),
      {
        name: "trailhead-cart",
        version: 1,
        partialize: (state) => ({ items: state.items }),
      },
    ),
    { name: "Cart", enabled: import.meta.env.DEV },
  ),
);

import { configureStore, createSlice, type PayloadAction } from "@reduxjs/toolkit";

type CartItem = { slug: string; quantity: number };

const cartSlice = createSlice({
  name: "cart",
  initialState: { items: [] as CartItem[] },
  reducers: {
    itemAdded(state, action: PayloadAction<string>) {
      const item = state.items.find((i) => i.slug === action.payload);
      if (item) item.quantity = Math.min(item.quantity + 1, 10);
      else state.items.push({ slug: action.payload, quantity: 1 });
    },
    cleared(state) {
      state.items = [];
    },
  },
});

export const { itemAdded, cleared } = cartSlice.actions;

export const store = configureStore({
  reducer: { cart: cartSlice.reducer },
});

export type RootState = ReturnType<typeof store.getState>;

